head.script:
scwin.onpageload = function () {
    // DataList에 초기 데이터 할당
    scwin.initData();
};

/**
 * DataList 'dlt_exam'에 데이터 할당하기
 */
scwin.initData = function () {
    // DataList 'dlt_exam'에 데이터 할당하기
    let data = [
        { "category": "Networking", "product": "SpeedLink" },
        { "category": "Cloud Services", "product": "CloudFlex" },
        { "category": "Support Services", "product": "TechAssist" },
        { "category": "Servers", "product": "EcoServe" },
        { "category": "Cloud Services", "product": "CloudPro" },
        { "category": "Support Services", "product": "TechTeam" },
        { "category": "Security", "product": "SecureGate" },
        { "category": "Networking", "product": "LinkSecure" },
        { "category": "Servers", "product": "ServeTech" }
    ];
    dlt_exam.setJSON(data);
};

/**
 * 버튼 ['Category' 컬럼의 값이 'Networking'과 일치하는 데이터 받기 - JSON 형식] 클릭 시
 */
scwin.btn_exam1_1_onclick = function (e) {
    // DataList 'dlt_exam'의 'Category' 컬럼의 값이 'Networking'과 일치하는 데이터를 JSON으로 반환받습니다.
    let result = dlt_exam.getMatchedJSON("category", "Networking");

    // 로그 출력
    let strLog = "# 'Category' 컬럼의 값이 'Networking'과 일치하는 데이터 받기 - JSON 형식 | 메소드 getMatchedJSON 호출 값";
    $c.frame.printExampleLog(strLog, txa_log_1, false);
    $c.frame.printExampleLog(JSON.stringify(result), txa_log_1, false);
    console.log(strLog);
    console.log(result);
};

/**
 * 버튼 ['Category' 컬럼의 값이 'Networking'과 일치하는 데이터 받기 - 1차원 Array 형식 + 컬럼 정보] 클릭 시
 */
scwin.btn_exam1_2_onclick = function (e) {
    // DataList 'dlt_exam'의 'Category' 컬럼의 값이 'Networking'과 일치하는 데이터를 '1차원 Array 형식 + 컬럼 정보'으로 반환받습니다.
    let result = dlt_exam.getMatchedArray("category", "Networking");

    // 로그 출력
    let strLog = "# 'Category' 컬럼의 값이 'Networking'과 일치하는 데이터 받기 - 1차원 Array 형식 + 컬럼 정보 | 메소드 getMatchedArray 호출 값";
    $c.frame.printExampleLog(strLog, txa_log_1, false);
    $c.frame.printExampleLog(JSON.stringify(result), txa_log_1, false);
    console.log(strLog);
    console.log(result);
};

/**
 * 버튼 ['Category' 컬럼의 값이 'Networking'과 일치하는 데이터 받기 - 2차원 Array 형식] 클릭 시
 */
scwin.btn_exam1_3_onclick = function (e) {
    // DataList 'dlt_exam'의 'Category' 컬럼의 값이 'Networking'과 일치하는 데이터를 '2차원 Array 형식'으로 반환받습니다.
    let result = dlt_exam.getMatchedData("category", "Networking");

    // 로그 출력
    let strLog = "# 'Category' 컬럼의 값이 'Networking'과 일치하는 데이터 받기 - 1차원 Array 형식 | 메소드 getMatchedData 호출 값";
    $c.frame.printExampleLog(strLog, txa_log_1, false);
    $c.frame.printExampleLog(JSON.stringify(result), txa_log_1, false);
    console.log(strLog);
    console.log(result);
};

/**
 * 버튼 ['Category' 컬럼의 값이 'Networking'과 일치하는 데이터 받기 - XML 형식] 클릭 시
 */
scwin.btn_exam1_4_onclick = function (e) {
    // DataList 'dlt_exam'의 'Category' 컬럼의 값이 'Networking'과 일치하는 데이터를 'XML' 형식으로 반환받습니다.
    let result = dlt_exam.getMatchedXML("category", "Networking");

    // 로그 출력
    let strLog = "# 'Category' 컬럼의 값이 'Networking'과 일치하는 데이터 받기 - XML 형식 | 메소드 getMatchedXML 호출 값";
    $c.frame.printExampleLog(strLog, txa_log_1, false);
    $c.frame.printExampleLog(WebSquare.xml.serialize(result), txa_log_1, false);
    console.log(strLog);
    console.log(result);
};

/**
 * 버튼 ['Category' 컬럼의 값이 'Networking'과 일치하는 Row Index 받기 - 1차원 Array 형식] 클릭 시
 */
scwin.btn_exam1_5_onclick = function (e) {
    // DataList 'dlt_exam'의 'Category' 컬럼의 값이 'Networking'과 일치하는 Row Index를 '1차원 Array'로 반환받습니다.
    let result = dlt_exam.getMatchedIndex("category", "Networking");

    // 로그 출력
    let strLog = "# 'Category' 컬럼의 값이 'Networking'과 일치하는 Row Index 받기 - 1차원 Array 형식 | 메소드 getMatchedIndex 호출 값";
    $c.frame.printExampleLog(strLog, txa_log_1, false);
    $c.frame.printExampleLog(JSON.stringify(result), txa_log_1, false);
    console.log(strLog);
    console.log(result);
};

/**
 * textarea의 로그 삭제
 */
scwin.btn_clearLog_onclick = function (e) {
    let strTargetId = this.getUserData("userData1");
    let cmpTarget;
    if (strTargetId) {
        cmpTarget = $p.getComponentById(strTargetId) || txa_log;
    } else {
        cmpTarget = txa_log;
    }
    //textarea value를 빈문자열로 할당.
    cmpTarget.setValue("");
};

/**
 * 버튼 ['Category' 컬럼의 값이 'Services'와 일치하는 데이터 받기 - JSON 형식] 클릭 시
 */
scwin.btn_exam2_1_onclick = function (e) {
    // DataList 'dlt_exam'의 'Category' 컬럼의 값이 'Services'와 일치하는 데이터를 JSON으로 반환받습니다.
    let result = dlt_exam.getMatchedJSON("category", "Services", true);

    // 로그 출력
    let strLog = "# 'Category' 컬럼의 값이 'Services'와 일치하는 데이터 받기 - JSON 형식 | 메소드 getMatchedJSON 호출 값";
    $c.frame.printExampleLog(strLog, txa_log_2, false);
    $c.frame.printExampleLog(JSON.stringify(result), txa_log_2, false);
    console.log(strLog);
    console.log(result);
};

/**
 * 버튼 ['Category' 컬럼의 값에 'Services'가 포함된 데이터 받기 - JSON 형식] 클릭 시
 */
scwin.btn_exam2_2_onclick = function (e) {
    // DataList 'dlt_exam'의 'Category' 컬럼의 값에 'Services'가 포함된 데이터를 JSON으로 반환받습니다.
    let result = dlt_exam.getMatchedJSON("category", "Services", false);

    // 로그 출력
    let strLog = "# 'Category' 컬럼의 값에 'Services'가 포함된 데이터 받기 - JSON 형식 | 메소드 getMatchedJSON 호출 값";
    $c.frame.printExampleLog(strLog, txa_log_2, false);
    $c.frame.printExampleLog(JSON.stringify(result), txa_log_2, false);
    console.log(strLog);
    console.log(result);
};



/**
 * 버튼 [전체 행을 대상으로 'Category' 컬럼의 값이 'Cloud Services'와 일치하는 데이터 받기 - JSON 형식]
 */
scwin.btn_exam3_1_onclick = function (e) {
    // DataList 'dlt_exam'의 전체 행을 대상으로 'Category' 컬럼의 값이 'Cloud Services'와 일치하는 데이터를 JSON으로 반환받습니다.
    let result = dlt_exam.getMatchedJSON("category", "Cloud Services", true);

    // 로그 출력
    let strLog = "# 전체 행을 대상으로 'Category' 컬럼의 값이 'Cloud Services'와 일치하는 데이터 받기 - JSON 형식 | 메소드 getMatchedJSON 호출 값";
    $c.frame.printExampleLog(strLog, txa_log_3, false);
    $c.frame.printExampleLog(JSON.stringify(result), txa_log_3, false);
    console.log(strLog);
    console.log(result);
};

/**
 * 버튼 [0~2번째 행을 대상으로 'Category' 컬럼의 값이 'Cloud Services'와 일치하는 데이터 받기 - JSON 형식]
 */
scwin.btn_exam3_2_onclick = function (e) {
    // DataList 'dlt_exam'의  0~2번째 행을 대상으로 'Category' 컬럼의 값이 'Cloud Services'와 일치하는 데이터를 JSON으로 반환받습니다.
    let result = dlt_exam.getMatchedJSON("category", "Cloud Services", true, 0, 2);

    // 로그 출력
    let strLog = "# 0~2번째 행을 대상으로 'Category' 컬럼의 값이 'Cloud Services'와 일치하는 데이터 받기 - JSON 형식 | 메소드 getMatchedJSON 호출 값";
    $c.frame.printExampleLog(strLog, txa_log_3, false);
    $c.frame.printExampleLog(JSON.stringify(result), txa_log_3, false);
    console.log(strLog);
    console.log(result);
};
